inputs.where:
@equals(and(
  contains(
    body('SPL_Properties_ID'),
    item()?['propertyId']
  ),
  not(
    contains(
      body('CMN_Properties_ID'),
      item()?['propertyId']
    )
  )
),true)

@equals(and(
  contains(
    body('SPL_Units_ID'),
    item()?['unitId']
  ),
  not(
    contains(
      body('Common_Units_ID'),
      item()?['unitId']
    )
  )
),true)

@equals(and(
  contains(
    body('SPL_Leases_ID'),
    item()?['leaseId']
  ),
  not(
    contains(
      body('Common_Leases_ID'),
      item()?['leaseId']
    )
  )
),true)

@equals(and(
  contains(
    body('SPL_PersonAcct_ID'),
    item()?['personbillingAccountId']
  ),
  not(
    contains(
      body('SHR_PersonAcct_ID'),
      item()?['personbillingAccountId']
    )
  )
),true)
